  &DefaultButton;




function dir$dmloaidx(p){
  this.constructor(p);
}
dir$dmloaidx.prototype = new DirEvent();
dir$dmloaidx.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmloaidx.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

dir$dmloaidxDisabledMasterField(p, g);

}

function dir$dmloaidxDisabledMasterField(p, g){

  if(p.valForm('ma_loaidx').trim() != '')
  {
    p.setDisabled('ma_loaidx', true);
  }
  else
  {
    p.setDisabled('ma_loaidx', false);
  }
}






	.control-label.ma_loaidx, .control-label.ten_loaidx
	{	
		//font-weight:bold;	
		color: #499b98;;
	}







